(7034593, 1068219, 94815, '<td valign="top">Strong image and a good take on the topic. Like mine I think the processing could be better esp some sharpening halos but I ultimately vote on content as long as it''s not destroyed by processing. 7</td>', 'Strong image and a good take on the topic. Like mine I think the processing could be better esp some sharpening halos but I ultimately vote on content as long as it''s not destroyed by processing. 7', '2013-05-08 17:10:25.000000', NULL, 1),
(7034594, 1068202, 94815, '<td valign="top">I learned a new word today. Thanks for that. Impressively minimal and grey. 7</td>', 'I learned a new word today. Thanks for that. Impressively minimal and grey. 7', '2013-05-08 17:12:00.000000', NULL, 1),
(7034600, 1067807, 94815, '<td valign="top">Very good find and an impressive take on some classic themes I think. Regardless, some subtle framing and compositional effects combined with the play on the battered and aged vs. youthful innocence make for a compelling image. 9</td>', 'Very good find and an impressive take on some classic themes I think. Regardless, some subtle framing and compositional effects combined with the play on the battered and aged vs. youthful innocence make for a compelling image. 9', '2013-05-08 17:19:00.000000', NULL, 1),
(7034604, 1067511, 94815, '<td valign="top">"...and not a drop to drink." The title has such strong associations with the Coleridge poem that my head can''t connect this with that. Better as "fire in the sky" playing off the "cool clear water". 6</td>', '"...and not a drop to drink." The title has such strong associations with the Coleridge poem that my head can''t connect this with that. Better as "fire in the sky" playing off the "cool clear water". 6', '2013-05-08 17:25:28.000000', NULL, 1),
